import "../test/install-local-storage-mock";
import { it, expect } from "vitest";
import { useProjectStore } from "../stores/project-store";
import { createEmptyProject } from "../stores/project/project-helpers";
import { captionTrack, makeCaption } from "./caption-project";
import { estimatedWords } from "./caption-data";
import { synchronizedRemoval, snapshotAction, rippleDeleteSelection } from "./commit";
import { useTimelineStore } from "../stores/timeline-store";
it("marked-range deletion takes precedence over clips, synchronizes tracks and restores one history entry", async () => {
  const project = createEmptyProject("Range");
  const transform = { position: { x: 0, y: 0 }, scale: { x: 1, y: 1 }, anchor: { x: 0.5, y: 0.5 }, rotation: 0, opacity: 1 };
  const clip = (id: string, trackId: string, startTime: number, duration: number, inPoint: number) => ({ id, trackId, startTime, duration, inPoint, outPoint: inPoint + duration * 2, speed: 2, mediaId: "source", transform, effects: [], audioEffects: [], volume: 0.5, keyframes: [] });
  const video = { ...captionTrack("Video"), id: "v", type: "video" as const, clips: [clip("v1", "v", 0, 8, 10)] };
  const audio = { ...captionTrack("Audio"), id: "a", type: "audio" as const, clips: [clip("a1", "a", 0, 8, 10)] };
  const early = { ...captionTrack("Unrelated"), id: "early", type: "video" as const, locked: true, clips: [clip("early1", "early", 0, 1, 0)] };
  const text = captionTrack();
  useProjectStore.getState().loadProject({ ...project, timeline: { ...project.timeline, duration: 8, tracks: [video, audio, early, text], subtitles: [{ id: "cue", text: "later", startTime: 5, endTime: 7 }] }, textClips: [makeCaption(project, text.id, "one two three four", 0, 8, { version: 1, kind: "caption", styleId: "clean", appearance: {}, animation: { effect: "none", duration: 0.25, intensity: 0.5 }, words: estimatedWords("one two three four", 8), timing: "verified-words", referenceDuration: 8, referenceFontSize: 1 })] });
  const before = useProjectStore.getState().getFullProject();
  useTimelineStore.getState().setLoopRange(2, 4);
  useTimelineStore.getState().seekTo(6);
  expect((await rippleDeleteSelection(useProjectStore.getState(), ["v1"])).success).toBe(true);
  const next = useProjectStore.getState().getFullProject();
  for (const track of next.timeline.tracks.slice(0, 2)) expect(track.clips.map((c) => [c.startTime, c.duration, c.inPoint, c.outPoint])).toEqual([[0, 2, 10, 14], [2, 4, 18, 26]]);
  expect(next.timeline.tracks[2]).toEqual(before.timeline.tracks[2]);
  expect(next.timeline.subtitles[0]).toMatchObject({ startTime: 3, endTime: 5 });
  expect(next.textClips?.map((c) => c.text).join(" ")).toBe("one three four");
  expect(useTimelineStore.getState().playheadPosition).toBe(4);
  expect(useTimelineStore.getState().loopEnd).toBe(0);
  await useProjectStore.getState().undo();
  expect(useProjectStore.getState().getFullProject().timeline).toEqual(before.timeline);
  expect(useProjectStore.getState().getFullProject().textClips).toEqual(before.textClips);
  await useProjectStore.getState().redo();
  expect(useProjectStore.getState().getFullProject().timeline).toEqual(next.timeline);
});
it("commits synchronized cuts and captions to the same native history with atomic undo/redo", async () => {
  const project = createEmptyProject("History");
  const track = captionTrack();
  const next = { ...project, timeline: { ...project.timeline, duration: 8, tracks: [track] }, textClips: [makeCaption(project, track.id, "one two three four", 0, 8, { version: 1, kind: "caption", styleId: "clean", appearance: {}, animation: { effect: "none", duration: 0.25, intensity: 0.5 }, words: estimatedWords("one two three four", 8), timing: "verified-words", referenceDuration: 8, referenceFontSize: 1 })] };
  useProjectStore.getState().loadProject(next);
  const original = JSON.stringify(useProjectStore.getState().getFullProject().textClips);
  expect((await synchronizedRemoval(useProjectStore.getState(), 2, 4)).success).toBe(true);
  expect(useProjectStore.getState().project.timeline.duration).toBe(6);
  expect((await useProjectStore.getState().undo()).success).toBe(true);
  expect(JSON.stringify(useProjectStore.getState().getFullProject().textClips)).toBe(original);
  expect(useProjectStore.getState().project.timeline.duration).toBe(8);
  expect((await useProjectStore.getState().redo()).success).toBe(true);
  const current = useProjectStore.getState().getFullProject();
  expect(current.textClips?.map((clip) => clip.text).join(" ")).toBe("one three four");
  expect((await useProjectStore.getState().executeAction(snapshotAction({ ...current, textClips: [] }))).success).toBe(true);
  await useProjectStore.getState().undo(); expect(useProjectStore.getState().getAllTextClips()).toHaveLength(2);
});
it("native caption split slices verified words and undoes atomically", () => {
  const state = useProjectStore.getState(), project = createEmptyProject("Split"); const track = captionTrack();
  const clip = makeCaption(project, track.id, "one two three four", 0, 8, { version: 1, kind: "caption", styleId: "clean", appearance: {}, animation: { effect: "none", duration: 0.25, intensity: 0.5 }, words: estimatedWords("one two three four", 8), timing: "verified-words", referenceDuration: 8, referenceFontSize: 1 });
  state.loadProject({ ...project, timeline: { ...project.timeline, tracks: [track], duration: 8 }, textClips: [clip] });
  const split = useProjectStore.getState().splitOverlayClip(clip.id, 4);
  expect(split?.left).toMatchObject({ text: "one two", duration: 4 }); expect(split?.right).toMatchObject({ text: "three four", startTime: 4, duration: 4 });
});
